public class Main {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in); int n = s.nextInt(); int[] a = new int[n], ans = new int[n];
        for (int i = 0; i < n; i++) a[i] = s.nextInt(); Arrays.fill(ans, -1);
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < n; i++) { while (!stack.isEmpty() && a[stack.peek()] < a[i]) ans[stack.pop()] = a[i]; stack.push(i); }
        StringBuilder out = new StringBuilder(); for (int i = 0; i < n; i++) { if (i > 0) out.append(' '); out.append(ans[i]); }
        System.out.println(out);
    }
}

